Creating a basic calculator using HTML is a great way to learn how web technologies can be used for simple applications. Below is a simple example of a working calculator that you can run in your browser:

```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Simple Calculator</title>
    <style>
        body {
            font-family: Arial, sans-serif;
            margin: 20px;
        }
        calculator {
            background-color: #f4f4f9;
            padding: 20px;
            border-radius: 5px;
        }
        input[type="text"] {
            width: 100%;
            height: 40px;
            margin-bottom: 10px;
            text-align: right;
        }
        button {
            width: 48%;
            padding: 10px;
            background-color: #4CAF50;
            color: white;
            border: none;
            cursor: pointer;
        }
        button:hover {
            background-color: #45a049;
        }
    </style>
</head>
<body>

<div class="calculator">
    <input type="text" id="display" readonly value="">
    <button onclick="appendNumber('7')">7</button>
    <button onclick="appendNumber('8')">8</button>
    <button onclick="appendNumber('9')">9</button>
    <button onclick="performOperation('/')">/</button><br>
    <button onclick="appendNumber('4')">4</button>
    <button onclick="appendNumber('5')">5</button>
    <button onclick="appendNumber('6')">6</button>
    <button onclick="performOperation('*')">*</button><br>
    <button onclick="appendNumber('1')">1</button>
    <button onclick="appendNumber('2')">2</button>
    <button onclick="appendNumber('3')">3</button>
    <button onclick="performOperation('-')">-</button><br>
    <button onclick="clearDisplay()">C</button>
    <button onclick="appendNumber('0')">0</button>
    <button onclick="calculateResult()">=</button>
    <button onclick="performOperation('+')">+</button>
</div>

<script>
    let display = document.getElementById("display");

    function appendNumber(number) {
        display.value += number;
    }

    function performOperation(operator) {
        display.value += operator;
    }

    function calculateResult() {
        try {
            display.value = eval(display.value);
        } catch (error) {
            display.value = "Error";
        }
    }

    function clearDisplay() {
        display.value = "";
    }
</script>

</body>
</html>
```

